                  "id": "root_kernel_arch_x86_64_linker_ld",
                  "name": "linker.ld",
                  "type": "file",
                  "path": "home/projects/SecureCurtain/sys/kernel/arch/x86_64/linker.ld",
                  "language": "text",
                  "description": "Source file linker.ld",
                  "content": "/* SecureCurtain OS Higher-Half x86_64 Linker Script\n * Author: Jared Busby (jb7572)\n * Target Architecture: ELF64 x86_64\n * Physical Entry: 1 MB (0x00100000)\n * Higher-Half Virtual Base: 0xFFFFFFFF80000000\n */\n\nOUTPUT_FORMAT(\"elf64-x86-64\")\nOUTPUT_ARCH(i386:x86-64)\nENTRY(_start)\n\nKERNEL_VIRTUAL_BASE = 0xFFFFFFFF80000000;\nKERNEL_PHYSICAL_BASE = 0x00100000;\n\nSECTIONS\n{\n    /* Physical load address starting at 1 MB */\n    . = KERNEL_PHYSICAL_BASE;\n\n    /* Early 32-bit Multiboot2 & page table bootstrap section (Physical address) */\n    .boot ALIGN(4K) :\n    {\n        KEEP(*(.multiboot_header))\n        *(.boot)\n    }\n\n    /* Transition to Higher-Half Virtual Address Space */\n    . += KERNEL_VIRTUAL_BASE;\n\n    /* 64-bit Kernel Code Section */\n    .text ALIGN(4K) : AT(ADDR(.text) - KERNEL_VIRTUAL_BASE)\n    {\n        _text_start = .;\n        *(.text .text.*)\n        _text_end = .;\n    }\n\n    /* Read-Only Data Section */\n    .rodata ALIGN(4K) : AT(ADDR(.rodata) - KERNEL_VIRTUAL_BASE)\n    {\n        _rodata_start = .;\n        *(.rodata .rodata.*)\n        _rodata_end = .;\n    }\n\n    /* Read-Write Initialized Data Section */\n    .data ALIGN(4K) : AT(ADDR(.data) - KERNEL_VIRTUAL_BASE)\n    {\n        _data_start = .;\n        *(.data .data.*)\n        _data_end = .;\n    }\n\n    /* Uninitialized Data & Kernel Stack Section */\n    .bss ALIGN(4K) : AT(ADDR(.bss) - KERNEL_VIRTUAL_BASE)\n    {\n        _bss_start = .;\n        *(COMMON)\n        *(.bss .bss.*)\n        _bss_end = .;\n    }\n\n    _kernel_end = .;\n\n    /DISCARD/ :\n    {\n        *(.comment)\n        *(.note*)\n        *(.eh_frame)\n    }\n}\n"
