                              "id": "root_kernel_include_linux_linux_6_10_10_include_linux_completion_h",
                              "name": "completion.h",
                              "type": "file",
                              "path": "home/projects/SecureCurtain/sys/kernel/include/linux/linux-6.10.10/include/linux/completion.h",
                              "language": "c",
                              "description": "Source file completion.h",
                              "content": "/* SPDX-License-Identifier: GPL-2.0 */\n#ifndef __LINUX_COMPLETION_H\n#define __LINUX_COMPLETION_H\n\n/*\n * (C) Copyright 2001 Linus Torvalds\n *\n * Atomic wait-for-completion handler data structures.\n * See kernel/sched/completion.c for details.\n */\n\n#include <linux/swait.h>\n\n/*\n * struct completion - structure used to maintain state for a \"completion\"\n *\n * This is the opaque structure used to maintain the state for a \"completion\".\n * Completions currently use a FIFO to queue threads that have to wait for\n * the \"completion\" event.\n *\n * See also:  complete(), wait_for_completion() (and friends _timeout,\n * _interruptible, _interruptible_timeout, and _killable), init_completion(),\n * reinit_completion(), and macros DECLARE_COMPLETION(),\n * DECLARE_COMPLETION_ONSTACK().\n */\nstruct completion {\n\tunsigned int done;\n\tstruct swait_queue_head wait;\n};\n\n#define init_completion_map(x, m) init_completion(x)\nstatic inline void complete_acquire(struct completion *x) {}\nstatic inline void complete_release(struct completion *x) {}\n\n#define COMPLETION_INITIALIZER(work) \\\n\t{ 0, __SWAIT_QUEUE_HEAD_INITIALIZER((work).wait) }\n\n#define COMPLETION_INITIALIZER_ONSTACK_MAP(work, map) \\\n\t(*({ init_completion_map(&(work), &(map)); &(work); }))\n\n#define COMPLETION_INITIALIZER_ONSTACK(work) \\\n\t(*({ init_completion(&work); &work; }))\n\n/**\n * DECLARE_COMPLETION - declare and initialize a completion structure\n * @work:  identifier for the completion structure\n *\n * This macro declares and initializes a completion structure. Generally used\n * for static declarations. You should use the _ONSTACK variant for automatic\n * variables.\n */\n#define DECLARE_COMPLETION(work) \\\n\tstruct completion work = COMPLETION_INITIALIZER(work)\n\n/*\n * Lockdep needs to run a non-constant initializer for on-stack\n * completions - so we use the _ONSTACK() variant for those that\n * are on the kernel stack:\n */\n/**\n * DECLARE_COMPLETION_ONSTACK - declare and initialize a completion structure\n * @work:  identifier for the completion structure\n *\n * This macro declares and initializes a completion structure on the kernel\n * stack.\n */\n#ifdef CONFIG_LOCKDEP\n# define DECLARE_COMPLETION_ONSTACK(work) \\\n\tstruct completion work = COMPLETION_INITIALIZER_ONSTACK(work)\n# define DECLARE_COMPLETION_ONSTACK_MAP(work, map) \\\n\tstruct completion work = COMPLETION_INITIALIZER_ONSTACK_MAP(work, map)\n#else\n# define DECLARE_COMPLETION_ONSTACK(work) DECLARE_COMPLETION(work)\n# define DECLARE_COMPLETION_ONSTACK_MAP(work, map) DECLARE_COMPLETION(work)\n#endif\n\n/**\n * init_completion - Initialize a dynamically allocated completion\n * @x:  pointer to completion structure that is to be initialized\n *\n * This inline function will initialize a dynamically created completion\n * structure.\n */\nstatic inline void init_completion(struct completion *x)\n{\n\tx->done = 0;\n\tinit_swait_queue_head(&x->wait);\n}\n\n/**\n * reinit_completion - reinitialize a completion structure\n * @x:  pointer to completion structure that is to be reinitialized\n *\n * This inline function should be used to reinitialize a completion structure so it can\n * be reused. This is especially important after complete_all() is used.\n */\nstatic inline void reinit_completion(struct completion *x)\n{\n\tx->done = 0;\n}\n\nextern void wait_for_completion(struct completion *);\nextern void wait_for_completion_io(struct completion *);\nextern int wait_for_completion_interruptible(struct completion *x);\nextern int wait_for_completion_killable(struct completion *x);\nextern int wait_for_completion_state(struct completion *x, unsigned int state);\nextern unsigned long wait_for_completion_timeout(struct completion *x,\n\t\t\t\t\t\t   unsigned long timeout);\nextern unsigned long wait_for_completion_io_timeout(struct completion *x,\n\t\t\t\t\t\t    unsigned long timeout);\nextern long wait_for_completion_interruptible_timeout(\n\tstruct completion *x, unsigned long timeout);\nextern long wait_for_completion_killable_timeout(\n\tstruct completion *x, unsigned long timeout);\nextern bool try_wait_for_completion(struct completion *x);\nextern bool completion_done(struct completion *x);\n\nextern void complete(struct completion *);\nextern void complete_on_current_cpu(struct completion *x);\nextern void complete_all(struct completion *);\n\n#endif\n"
