                              "id": "root_kernel_include_linux_linux_6_10_10_include_linux_component_h",
                              "name": "component.h",
                              "type": "file",
                              "path": "home/projects/SecureCurtain/sys/kernel/include/linux/linux-6.10.10/include/linux/component.h",
                              "language": "c",
                              "description": "Source file component.h",
                              "content": "/* SPDX-License-Identifier: GPL-2.0 */\n#ifndef COMPONENT_H\n#define COMPONENT_H\n\n#include <linux/stddef.h>\n\n\nstruct device;\n\n/**\n * struct component_ops - callbacks for component drivers\n *\n * Components are registered with component_add() and unregistered with\n * component_del().\n */\nstruct component_ops {\n\t/**\n\t * @bind:\n\t *\n\t * Called through component_bind_all() when the aggregate driver is\n\t * ready to bind the overall driver.\n\t */\n\tint (*bind)(struct device *comp, struct device *master,\n\t\t    void *master_data);\n\t/**\n\t * @unbind:\n\t *\n\t * Called through component_unbind_all() when the aggregate driver is\n\t * ready to bind the overall driver, or when component_bind_all() fails\n\t * part-ways through and needs to unbind some already bound components.\n\t */\n\tvoid (*unbind)(struct device *comp, struct device *master,\n\t\t       void *master_data);\n};\n\nint component_add(struct device *, const struct component_ops *);\nint component_add_typed(struct device *dev, const struct component_ops *ops,\n\tint subcomponent);\nvoid component_del(struct device *, const struct component_ops *);\n\nint component_bind_all(struct device *parent, void *data);\nvoid component_unbind_all(struct device *parent, void *data);\n\nstruct aggregate_device;\n\n/**\n * struct component_master_ops - callback for the aggregate driver\n *\n * Aggregate drivers are registered with component_master_add_with_match() and\n * unregistered with component_master_del().\n */\nstruct component_master_ops {\n\t/**\n\t * @bind:\n\t *\n\t * Called when all components or the aggregate driver, as specified in\n\t * the match list passed to component_master_add_with_match(), are\n\t * ready. Usually there are 3 steps to bind an aggregate driver:\n\t *\n\t * 1. Allocate a structure for the aggregate driver.\n\t *\n\t * 2. Bind all components to the aggregate driver by calling\n\t *    component_bind_all() with the aggregate driver structure as opaque\n\t *    pointer data.\n\t *\n\t * 3. Register the aggregate driver with the subsystem to publish its\n\t *    interfaces.\n\t *\n\t * Note that the lifetime of the aggregate driver does not align with\n\t * any of the underlying &struct device instances. Therefore devm cannot\n\t * be used and all resources acquired or allocated in this callback must\n\t * be explicitly released in the @unbind callback.\n\t */\n\tint (*bind)(struct device *master);\n\t/**\n\t * @unbind:\n\t *\n\t * Called when either the aggregate driver, using\n\t * component_master_del(), or one of its components, using\n\t * component_del(), is unregistered.\n\t */\n\tvoid (*unbind)(struct device *master);\n};\n\n/* A set helper functions for component compare/release */\nint component_compare_of(struct device *dev, void *data);\nvoid component_release_of(struct device *dev, void *data);\nint component_compare_dev(struct device *dev, void *data);\nint component_compare_dev_name(struct device *dev, void *data);\n\nvoid component_master_del(struct device *,\n\tconst struct component_master_ops *);\n\nstruct component_match;\n\nint component_master_add_with_match(struct device *,\n\tconst struct component_master_ops *, struct component_match *);\nvoid component_match_add_release(struct device *parent,\n\tstruct component_match **matchptr,\n\tvoid (*release)(struct device *, void *),\n\tint (*compare)(struct device *, void *), void *compare_data);\nvoid component_match_add_typed(struct device *parent,\n\tstruct component_match **matchptr,\n\tint (*compare_typed)(struct device *, int, void *), void *compare_data);\n\n/**\n * component_match_add - add a component match entry\n * @parent: device with the aggregate driver\n * @matchptr: pointer to the list of component matches\n * @compare: compare function to match against all components\n * @compare_data: opaque pointer passed to the @compare function\n *\n * Adds a new component match to the list stored in @matchptr, which the @parent\n * aggregate driver needs to function. The list of component matches pointed to\n * by @matchptr must be initialized to NULL before adding the first match. This\n * only matches against components added with component_add().\n *\n * The allocated match list in @matchptr is automatically released using devm\n * actions.\n *\n * See also component_match_add_release() and component_match_add_typed().\n */\nstatic inline void component_match_add(struct device *parent,\n\tstruct component_match **matchptr,\n\tint (*compare)(struct device *, void *), void *compare_data)\n{\n\tcomponent_match_add_release(parent, matchptr, NULL, compare,\n\t\t\t\t    compare_data);\n}\n\n#endif\n"
