                              "id": "root_kernel_include_linux_linux_6_10_10_include_linux_dnotify_h",
                              "name": "dnotify.h",
                              "type": "file",
                              "path": "home/projects/SecureCurtain/sys/kernel/include/linux/linux-6.10.10/include/linux/dnotify.h",
                              "language": "c",
                              "description": "Source file dnotify.h",
                              "content": "/* SPDX-License-Identifier: GPL-2.0 */\n#ifndef _LINUX_DNOTIFY_H\n#define _LINUX_DNOTIFY_H\n/*\n * Directory notification for Linux\n *\n * Copyright (C) 2000,2002 Stephen Rothwell\n */\n\n#include <linux/fs.h>\n\nstruct dnotify_struct {\n\tstruct dnotify_struct *\tdn_next;\n\t__u32\t\t\tdn_mask;\n\tint\t\t\tdn_fd;\n\tstruct file *\t\tdn_filp;\n\tfl_owner_t\t\tdn_owner;\n};\n\n#ifdef __KERNEL__\n\n\n#ifdef CONFIG_DNOTIFY\n\n#define DNOTIFY_ALL_EVENTS (FS_DELETE | FS_DELETE_CHILD |\\\n\t\t\t    FS_MODIFY | FS_MODIFY_CHILD |\\\n\t\t\t    FS_ACCESS | FS_ACCESS_CHILD |\\\n\t\t\t    FS_ATTRIB | FS_ATTRIB_CHILD |\\\n\t\t\t    FS_CREATE | FS_RENAME |\\\n\t\t\t    FS_MOVED_FROM | FS_MOVED_TO)\n\nextern void dnotify_flush(struct file *, fl_owner_t);\nextern int fcntl_dirnotify(int, struct file *, unsigned int);\n\n#else\n\nstatic inline void dnotify_flush(struct file *filp, fl_owner_t id)\n{\n}\n\nstatic inline int fcntl_dirnotify(int fd, struct file *filp, unsigned int arg)\n{\n\treturn -EINVAL;\n}\n\n#endif /* CONFIG_DNOTIFY */\n\n#endif /* __KERNEL __ */\n\n#endif /* _LINUX_DNOTIFY_H */\n"
