                                  "language": "c",
                                  "description": "Source file fpga-bridge.h",
                                  "content": "/* SPDX-License-Identifier: GPL-2.0 */\n\n#ifndef _LINUX_FPGA_BRIDGE_H\n#define _LINUX_FPGA_BRIDGE_H\n\n#include <linux/device.h>\n#include <linux/fpga/fpga-mgr.h>\n\nstruct fpga_bridge;\n\n/**\n * struct fpga_bridge_ops - ops for low level FPGA bridge drivers\n * @enable_show: returns the FPGA bridge's status\n * @enable_set: set an FPGA bridge as enabled or disabled\n * @fpga_bridge_remove: set FPGA into a specific state during driver remove\n * @groups: optional attribute groups.\n */\nstruct fpga_bridge_ops {\n\tint (*enable_show)(struct fpga_bridge *bridge);\n\tint (*enable_set)(struct fpga_bridge *bridge, bool enable);\n\tvoid (*fpga_bridge_remove)(struct fpga_bridge *bridge);\n\tconst struct attribute_group **groups;\n};\n\n/**\n * struct fpga_bridge_info - collection of parameters an FPGA Bridge\n * @name: fpga bridge name\n * @br_ops: pointer to structure of fpga bridge ops\n * @priv: fpga bridge private data\n *\n * fpga_bridge_info contains parameters for the register function. These\n * are separated into an info structure because they some are optional\n * others could be added to in the future. The info structure facilitates\n * maintaining a stable API.\n */\nstruct fpga_bridge_info {\n\tconst char *name;\n\tconst struct fpga_bridge_ops *br_ops;\n\tvoid *priv;\n};\n\n/**\n * struct fpga_bridge - FPGA bridge structure\n * @name: name of low level FPGA bridge\n * @dev: FPGA bridge device\n * @mutex: enforces exclusive reference to bridge\n * @br_ops: pointer to struct of FPGA bridge ops\n * @br_ops_owner: module containing the br_ops\n * @info: fpga image specific information\n * @node: FPGA bridge list node\n * @priv: low level driver private date\n */\nstruct fpga_bridge {\n\tconst char *name;\n\tstruct device dev;\n\tstruct mutex mutex; /* for exclusive reference to bridge */\n\tconst struct fpga_bridge_ops *br_ops;\n\tstruct module *br_ops_owner;\n\tstruct fpga_image_info *info;\n\tstruct list_head node;\n\tvoid *priv;\n};\n\n#define to_fpga_bridge(d) container_of(d, struct fpga_bridge, dev)\n\nstruct fpga_bridge *of_fpga_bridge_get(struct device_node *node,\n\t\t\t\t       struct fpga_image_info *info);\nstruct fpga_bridge *fpga_bridge_get(struct device *dev,\n\t\t\t\t    struct fpga_image_info *info);\nvoid fpga_bridge_put(struct fpga_bridge *bridge);\nint fpga_bridge_enable(struct fpga_bridge *bridge);\nint fpga_bridge_disable(struct fpga_bridge *bridge);\n\nint fpga_bridges_enable(struct list_head *bridge_list);\nint fpga_bridges_disable(struct list_head *bridge_list);\nvoid fpga_bridges_put(struct list_head *bridge_list);\nint fpga_bridge_get_to_list(struct device *dev,\n\t\t\t    struct fpga_image_info *info,\n\t\t\t    struct list_head *bridge_list);\nint of_fpga_bridge_get_to_list(struct device_node *np,\n\t\t\t       struct fpga_image_info *info,\n\t\t\t       struct list_head *bridge_list);\n\n#define fpga_bridge_register(parent, name, br_ops, priv) \\\n\t__fpga_bridge_register(parent, name, br_ops, priv, THIS_MODULE)\nstruct fpga_bridge *\n__fpga_bridge_register(struct device *parent, const char *name,\n\t\t       const struct fpga_bridge_ops *br_ops, void *priv,\n\t\t       struct module *owner);\nvoid fpga_bridge_unregister(struct fpga_bridge *br);\n\n#endif /* _LINUX_FPGA_BRIDGE_H */\n"
