                                    {
                                      "id": "root_kernel_include_linux_linux_6_10_10_include_linux_iio_afe_rescale_h",
                                      "name": "rescale.h",
                                      "type": "file",
                                      "path": "home/projects/SecureCurtain/sys/kernel/include/linux/linux-6.10.10/include/linux/iio/afe/rescale.h",
                                      "language": "c",
                                      "description": "Source file rescale.h",
                                      "content": "/* SPDX-License-Identifier: GPL-2.0-only */\n/*\n * Copyright (C) 2018 Axentia Technologies AB\n */\n\n#ifndef __IIO_RESCALE_H__\n#define __IIO_RESCALE_H__\n\n#include <linux/types.h>\n#include <linux/iio/iio.h>\n\nstruct device;\nstruct rescale;\n\nstruct rescale_cfg {\n\tenum iio_chan_type type;\n\tint (*props)(struct device *dev, struct rescale *rescale);\n};\n\nstruct rescale {\n\tconst struct rescale_cfg *cfg;\n\tstruct iio_channel *source;\n\tstruct iio_chan_spec chan;\n\tstruct iio_chan_spec_ext_info *ext_info;\n\tbool chan_processed;\n\ts32 numerator;\n\ts32 denominator;\n\ts32 offset;\n};\n\nint rescale_process_scale(struct rescale *rescale, int scale_type,\n\t\t\t  int *val, int *val2);\nint rescale_process_offset(struct rescale *rescale, int scale_type,\n\t\t\t   int scale, int scale2, int schan_off,\n\t\t\t   int *val, int *val2);\n#endif /* __IIO_RESCALE_H__ */\n"
                                    }
