                              "id": "root_kernel_include_linux_linux_6_10_10_include_linux_nospec_h",
                              "name": "nospec.h",
                              "type": "file",
                              "path": "home/projects/SecureCurtain/sys/kernel/include/linux/linux-6.10.10/include/linux/nospec.h",
                              "language": "c",
                              "description": "Source file nospec.h",
                              "content": "// SPDX-License-Identifier: GPL-2.0\n// Copyright(c) 2018 Linus Torvalds. All rights reserved.\n// Copyright(c) 2018 Alexei Starovoitov. All rights reserved.\n// Copyright(c) 2018 Intel Corporation. All rights reserved.\n\n#ifndef _LINUX_NOSPEC_H\n#define _LINUX_NOSPEC_H\n\n#include <linux/compiler.h>\n#include <asm/barrier.h>\n\nstruct task_struct;\n\n#ifndef barrier_nospec\n# define barrier_nospec() do { } while (0)\n#endif\n\n/**\n * array_index_mask_nospec() - generate a ~0 mask when index < size, 0 otherwise\n * @index: array element index\n * @size: number of elements in array\n *\n * When @index is out of bounds (@index >= @size), the sign bit will be\n * set.  Extend the sign bit to all bits and invert, giving a result of\n * zero for an out of bounds index, or ~0 if within bounds [0, @size).\n */\n#ifndef array_index_mask_nospec\nstatic inline unsigned long array_index_mask_nospec(unsigned long index,\n\t\t\t\t\t\t    unsigned long size)\n{\n\t/*\n\t * Always calculate and emit the mask even if the compiler\n\t * thinks the mask is not needed. The compiler does not take\n\t * into account the value of @index under speculation.\n\t */\n\tOPTIMIZER_HIDE_VAR(index);\n\treturn ~(long)(index | (size - 1UL - index)) >> (BITS_PER_LONG - 1);\n}\n#endif\n\n/*\n * array_index_nospec - sanitize an array index after a bounds check\n *\n * For a code sequence like:\n *\n *     if (index < size) {\n *         index = array_index_nospec(index, size);\n *         val = array[index];\n *     }\n *\n * ...if the CPU speculates past the bounds check then\n * array_index_nospec() will clamp the index within the range of [0,\n * size).\n */\n#define array_index_nospec(index, size)\t\t\t\t\t\\\n({\t\t\t\t\t\t\t\t\t\\\n\ttypeof(index) _i = (index);\t\t\t\t\t\\\n\ttypeof(size) _s = (size);\t\t\t\t\t\\\n\tunsigned long _mask = array_index_mask_nospec(_i, _s);\t\t\\\n\t\t\t\t\t\t\t\t\t\\\n\tBUILD_BUG_ON(sizeof(_i) > sizeof(long));\t\t\t\\\n\tBUILD_BUG_ON(sizeof(_s) > sizeof(long));\t\t\t\\\n\t\t\t\t\t\t\t\t\t\\\n\t(typeof(_i)) (_i & _mask);\t\t\t\t\t\\\n})\n\n/* Speculation control prctl */\nint arch_prctl_spec_ctrl_get(struct task_struct *task, unsigned long which);\nint arch_prctl_spec_ctrl_set(struct task_struct *task, unsigned long which,\n\t\t\t     unsigned long ctrl);\n/* Speculation control for seccomp enforced mitigation */\nvoid arch_seccomp_spec_mitigate(struct task_struct *task);\n\n#endif /* _LINUX_NOSPEC_H */\n"
