                              "content": "/* SPDX-License-Identifier: GPL-2.0 */\n/*\n * nvmem framework consumer.\n *\n * Copyright (C) 2015 Srinivas Kandagatla <srinivas.kandagatla@linaro.org>\n * Copyright (C) 2013 Maxime Ripard <maxime.ripard@free-electrons.com>\n */\n\n#ifndef _LINUX_NVMEM_CONSUMER_H\n#define _LINUX_NVMEM_CONSUMER_H\n\n#include <linux/err.h>\n#include <linux/errno.h>\n#include <linux/notifier.h>\n\nstruct device;\nstruct device_node;\n/* consumer cookie */\nstruct nvmem_cell;\nstruct nvmem_device;\nstruct nvmem_cell_info;\n\n/**\n * struct nvmem_cell_lookup - cell lookup entry\n *\n * @nvmem_name:\tName of the provider.\n * @cell_name:\tName of the nvmem cell as defined in the name field of\n *\t\tstruct nvmem_cell_info.\n * @dev_id:\tName of the consumer device that will be associated with\n *\t\tthis cell.\n * @con_id:\tConnector id for this cell lookup.\n */\nstruct nvmem_cell_lookup {\n\tconst char\t\t*nvmem_name;\n\tconst char\t\t*cell_name;\n\tconst char\t\t*dev_id;\n\tconst char\t\t*con_id;\n\tstruct list_head\tnode;\n};\n\nenum {\n\tNVMEM_ADD = 1,\n\tNVMEM_REMOVE,\n\tNVMEM_CELL_ADD,\n\tNVMEM_CELL_REMOVE,\n\tNVMEM_LAYOUT_ADD,\n\tNVMEM_LAYOUT_REMOVE,\n};\n\n#if IS_ENABLED(CONFIG_NVMEM)\n\n/* Cell based interface */\nstruct nvmem_cell *nvmem_cell_get(struct device *dev, const char *id);\nstruct nvmem_cell *devm_nvmem_cell_get(struct device *dev, const char *id);\nvoid nvmem_cell_put(struct nvmem_cell *cell);\nvoid devm_nvmem_cell_put(struct device *dev, struct nvmem_cell *cell);\nvoid *nvmem_cell_read(struct nvmem_cell *cell, size_t *len);\nint nvmem_cell_write(struct nvmem_cell *cell, void *buf, size_t len);\nint nvmem_cell_read_u8(struct device *dev, const char *cell_id, u8 *val);\nint nvmem_cell_read_u16(struct device *dev, const char *cell_id, u16 *val);\nint nvmem_cell_read_u32(struct device *dev, const char *cell_id, u32 *val);\nint nvmem_cell_read_u64(struct device *dev, const char *cell_id, u64 *val);\nint nvmem_cell_read_variable_le_u32(struct device *dev, const char *cell_id,\n\t\t\t\t    u32 *val);\nint nvmem_cell_read_variable_le_u64(struct device *dev, const char *cell_id,\n\t\t\t\t    u64 *val);\n\n/* direct nvmem device read/write interface */\nstruct nvmem_device *nvmem_device_get(struct device *dev, const char *name);\nstruct nvmem_device *devm_nvmem_device_get(struct device *dev,\n\t\t\t\t\t   const char *name);\nvoid nvmem_device_put(struct nvmem_device *nvmem);\nvoid devm_nvmem_device_put(struct device *dev, struct nvmem_device *nvmem);\nint nvmem_device_read(struct nvmem_device *nvmem, unsigned int offset,\n\t\t      size_t bytes, void *buf);\nint nvmem_device_write(struct nvmem_device *nvmem, unsigned int offset,\n\t\t       size_t bytes, void *buf);\nssize_t nvmem_device_cell_read(struct nvmem_device *nvmem,\n\t\t\t   struct nvmem_cell_info *info, void *buf);\nint nvmem_device_cell_write(struct nvmem_device *nvmem,\n\t\t\t    struct nvmem_cell_info *info, void *buf);\n\nconst char *nvmem_dev_name(struct nvmem_device *nvmem);\nsize_t nvmem_dev_size(struct nvmem_device *nvmem);\n\nvoid nvmem_add_cell_lookups(struct nvmem_cell_lookup *entries,\n\t\t\t    size_t nentries);\nvoid nvmem_del_cell_lookups(struct nvmem_cell_lookup *entries,\n\t\t\t    size_t nentries);\n\nint nvmem_register_notifier(struct notifier_block *nb);\nint nvmem_unregister_notifier(struct notifier_block *nb);\n\nstruct nvmem_device *nvmem_device_find(void *data,\n\t\t\tint (*match)(struct device *dev, const void *data));\n\n#else\n\nstatic inline struct nvmem_cell *nvmem_cell_get(struct device *dev,\n\t\t\t\t\t\tconst char *id)\n{\n\treturn ERR_PTR(-EOPNOTSUPP);\n}\n\nstatic inline struct nvmem_cell *devm_nvmem_cell_get(struct device *dev,\n\t\t\t\t\t\t     const char *id)\n{\n\treturn ERR_PTR(-EOPNOTSUPP);\n}\n\nstatic inline void devm_nvmem_cell_put(struct device *dev,\n\t\t\t\t       struct nvmem_cell *cell)\n{\n\n}\nstatic inline void nvmem_cell_put(struct nvmem_cell *cell)\n{\n}\n\nstatic inline void *nvmem_cell_read(struct nvmem_cell *cell, size_t *len)\n{\n\treturn ERR_PTR(-EOPNOTSUPP);\n}\n\nstatic inline int nvmem_cell_write(struct nvmem_cell *cell,\n\t\t\t\t   void *buf, size_t len)\n{\n\treturn -EOPNOTSUPP;\n}\n\nstatic inline int nvmem_cell_read_u8(struct device *dev,\n\t\t\t\t     const char *cell_id, u8 *val)\n{\n\treturn -EOPNOTSUPP;\n}\n\nstatic inline int nvmem_cell_read_u16(struct device *dev,\n\t\t\t\t      const char *cell_id, u16 *val)\n{\n\treturn -EOPNOTSUPP;\n}\n\nstatic inline int nvmem_cell_read_u32(struct device *dev,\n\t\t\t\t      const char *cell_id, u32 *val)\n{\n\treturn -EOPNOTSUPP;\n}\n\nstatic inline int nvmem_cell_read_u64(struct device *dev,\n\t\t\t\t      const char *cell_id, u64 *val)\n{\n\treturn -EOPNOTSUPP;\n}\n\nstatic inline int nvmem_cell_read_variable_le_u32(struct device *dev,\n\t\t\t\t\t\t const char *cell_id,\n\t\t\t\t\t\t u32 *val)\n{\n\treturn -EOPNOTSUPP;\n}\n\nstatic inline int nvmem_cell_read_variable_le_u64(struct device *dev,\n\t\t\t\t\t\t  const char *cell_id,\n\t\t\t\t\t\t  u64 *val)\n{\n\treturn -EOPNOTSUPP;\n}\n\nstatic inline struct nvmem_device *nvmem_device_get(struct device *dev,\n\t\t\t\t\t\t    const char *name)\n{\n\treturn ERR_PTR(-EOPNOTSUPP);\n}\n\nstatic inline struct nvmem_device *devm_nvmem_device_get(struct device *dev,\n\t\t\t\t\t\t\t const char *name)\n{\n\treturn ERR_PTR(-EOPNOTSUPP);\n}\n\nstatic inline void nvmem_device_put(struct nvmem_device *nvmem)\n{\n}\n\nstatic inline void devm_nvmem_device_put(struct device *dev,\n\t\t\t\t\t struct nvmem_device *nvmem)\n{\n}\n\nstatic inline ssize_t nvmem_device_cell_read(struct nvmem_device *nvmem,\n\t\t\t\t\t struct nvmem_cell_info *info,\n\t\t\t\t\t void *buf)\n{\n\treturn -EOPNOTSUPP;\n}\n\nstatic inline int nvmem_device_cell_write(struct nvmem_device *nvmem,\n\t\t\t\t\t  struct nvmem_cell_info *info,\n\t\t\t\t\t  void *buf)\n{\n\treturn -EOPNOTSUPP;\n}\n\nstatic inline int nvmem_device_read(struct nvmem_device *nvmem,\n\t\t\t\t    unsigned int offset, size_t bytes,\n\t\t\t\t    void *buf)\n{\n\treturn -EOPNOTSUPP;\n}\n\nstatic inline int nvmem_device_write(struct nvmem_device *nvmem,\n\t\t\t\t     unsigned int offset, size_t bytes,\n\t\t\t\t     void *buf)\n{\n\treturn -EOPNOTSUPP;\n}\n\nstatic inline const char *nvmem_dev_name(struct nvmem_device *nvmem)\n{\n\treturn NULL;\n}\n\nstatic inline void\nnvmem_add_cell_lookups(struct nvmem_cell_lookup *entries, size_t nentries) {}\nstatic inline void\nnvmem_del_cell_lookups(struct nvmem_cell_lookup *entries, size_t nentries) {}\n\nstatic inline int nvmem_register_notifier(struct notifier_block *nb)\n{\n\treturn -EOPNOTSUPP;\n}\n\nstatic inline int nvmem_unregister_notifier(struct notifier_block *nb)\n{\n\treturn -EOPNOTSUPP;\n}\n\nstatic inline struct nvmem_device *nvmem_device_find(void *data,\n\t\t\tint (*match)(struct device *dev, const void *data))\n{\n\treturn NULL;\n}\n\n#endif /* CONFIG_NVMEM */\n\n#if IS_ENABLED(CONFIG_NVMEM) && IS_ENABLED(CONFIG_OF)\nstruct nvmem_cell *of_nvmem_cell_get(struct device_node *np,\n\t\t\t\t     const char *id);\nstruct nvmem_device *of_nvmem_device_get(struct device_node *np,\n\t\t\t\t\t const char *name);\n#else\nstatic inline struct nvmem_cell *of_nvmem_cell_get(struct device_node *np,\n\t\t\t\t\t\t   const char *id)\n{\n\treturn ERR_PTR(-EOPNOTSUPP);\n}\n\nstatic inline struct nvmem_device *of_nvmem_device_get(struct device_node *np,\n\t\t\t\t\t\t       const char *name)\n{\n\treturn ERR_PTR(-EOPNOTSUPP);\n}\n#endif /* CONFIG_NVMEM && CONFIG_OF */\n\n#endif  /* ifndef _LINUX_NVMEM_CONSUMER_H */\n"
