              "content": "#pragma once\n#include <stdint.h>\n#include <stddef.h>\n\ntypedef void* EFI_HANDLE;\ntypedef size_t EFI_STATUS;\n\n#define EFI_SUCCESS 0\n\ntypedef struct {\n    uint32_t Data1;\n    uint16_t Data2;\n    uint16_t Data3;\n    uint8_t  Data4[8];\n} EFI_GUID;\n\n#define EFI_GRAPHICS_OUTPUT_PROTOCOL_GUID     {0x9042a9de, 0x23dc, 0x4a38, {0x96, 0xfb, 0x7a, 0xde, 0xd0, 0x80, 0x51, 0x6a}}\n\ntypedef struct {\n    uint32_t Version;\n    uint32_t HorizontalResolution;\n    uint32_t VerticalResolution;\n    uint32_t PixelFormat;\n    uint32_t PixelInformation[4];\n    uint32_t PixelsPerScanLine;\n} EFI_GRAPHICS_OUTPUT_MODE_INFORMATION;\n\ntypedef struct {\n    uint32_t MaxMode;\n    uint32_t Mode;\n    EFI_GRAPHICS_OUTPUT_MODE_INFORMATION* Info;\n    size_t SizeOfInfo;\n    uint64_t FrameBufferBase;\n    size_t FrameBufferSize;\n} EFI_GRAPHICS_OUTPUT_PROTOCOL_MODE;\n\ntypedef struct {\n    void* QueryMode;\n    void* SetMode;\n    void* Blt;\n    EFI_GRAPHICS_OUTPUT_PROTOCOL_MODE* Mode;\n} EFI_GRAPHICS_OUTPUT_PROTOCOL;\n\ntypedef struct {\n    uint32_t Type;\n    uint32_t Reserved;\n    uint64_t PhysicalStart;\n    uint64_t VirtualStart;\n    uint64_t NumberOfPages;\n    uint64_t Attribute;\n} EFI_MEMORY_DESCRIPTOR;\n\ntypedef struct {\n    void* RaiseTPL;\n    void* RestoreTPL;\n    void* AllocatePages;\n    void* FreePages;\n    EFI_STATUS (*GetMemoryMap)(size_t* MemoryMapSize, EFI_MEMORY_DESCRIPTOR* MemoryMap, size_t* MapKey, size_t* DescriptorSize, uint32_t* DescriptorVersion);\n    void* AllocatePool;\n    void* FreePool;\n    void* CreateEvent;\n    void* SetTimer;\n    void* WaitForEvent;\n    void* SignalEvent;\n    void* CloseEvent;\n    void* CheckEvent;\n    void* InstallProtocolInterface;\n    void* ReinstallProtocolInterface;\n    void* UninstallProtocolInterface;\n    void* HandleProtocol;\n    void* Reserved;\n    void* RegisterProtocolNotify;\n    EFI_STATUS (*LocateProtocol)(EFI_GUID* Protocol, void* Registration, void** Interface);\n    void* KeyNotify;\n    void* OpenProtocolInformation;\n    void* ProtocolsPerHandle;\n    void* LocateHandleBuffer;\n    void* LocateProtocol2;\n    void* InstallMultipleProtocolInterfaces;\n    void* UninstallMultipleProtocolInterfaces;\n    void* CalculateCrc32;\n    void* CopyMem;\n    void* SetMem;\n    void* CreateEventEx;\n    EFI_STATUS (*ExitBootServices)(EFI_HANDLE ImageHandle, size_t MapKey);\n} EFI_BOOT_SERVICES;\n\ntypedef struct {\n    char Header[24];\n    void* FirmwareVendor;\n    uint32_t FirmwareRevision;\n    void* ConsoleInHandle;\n    void* ConIn;\n    void* ConsoleOutHandle;\n    void* ConOut;\n    void* StandardErrorHandle;\n    void* StdErr;\n    void* RuntimeServices;\n    EFI_BOOT_SERVICES* BootServices;\n} EFI_SYSTEM_TABLE;"
